-- Safety III — Arc Flash, PPE & Safety Equipment
insert into public.roadmap_modules (
  id, phase, phase_title, order_in_phase, title, description, domain, neta_reference,
  estimated_minutes, total_questions, content_sections, is_published, passing_score,
  neta_level, video_recommended
) values (
  'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58', 1, 'Foundation', 4, $sfty$Safety III — Arc Flash, PPE & Safety Equipment$sfty$, $sfty$Arc flash boundaries and labels, what drives incident energy, PPE categories and arc-rated clothing, rubber insulating gloves, and choosing and caring for safety equipment.$sfty$,
  'Safety', $sfty$NFPA 70E 130.5, 130.7; ASTM D120/F496; IEEE 1584; NEC 240.87; NETA L2 Outline Safety D, E, H$sfty$, 35, 10,
  $sfty${"overview": "Arc flash is the hazard that NETA technicians face most directly, because testing and troubleshooting often happen near energized gear. This module covers the arc flash boundary and how to read an arc flash label, what to do when there isn't one, the factors that drive incident energy (and why maintenance testing lowers it), the PPE category system, and the shock-protection equipment you'll use every day: rubber gloves, hot sticks, voltage detectors and insulated tools — including how to inspect, store and test them.", "sections": [{"title": "Arc Flash Risk Assessment and the Arc Flash Boundary", "content": "The arc flash risk assessment determines whether an arc flash hazard exists, and if it does, the protective measures and PPE needed. The arc flash boundary is the distance from the arc source at which incident energy equals 1.2 cal/cm² (5 J/cm²) — the onset of a second-degree burn on bare skin. Anyone inside that boundary needs arc flash PPE. PPE can be selected one of two ways: the incident energy analysis method (an engineering study, usually per IEEE 1584, that calculates cal/cm² at a working distance), or the arc flash PPE category method using NFPA 70E's tables. Use one method or the other on a given piece of equipment, never both, and don't use an incident energy result to pick a table category. The incident energy analysis must account for the protective device's clearing time and its condition of maintenance. It must be updated when the system changes, and reviewed at least every 5 years.", "key_points": ["Arc flash boundary = distance where incident energy is 1.2 cal/cm² (5 J/cm²)", "Two PPE methods: incident energy analysis OR PPE category tables — never both on the same equipment", "Analysis considers the protective device's clearing time and maintenance condition", "Update on system changes; review at intervals not exceeding 5 years"], "standards_reference": "NFPA 70E 130.5(A)–(G); IEEE 1584; NETA L2 Outline Safety H.3"}, {"title": "Reading Arc Flash Labels — and When There Isn't One", "content": "Equipment likely to be examined, adjusted, serviced or maintained while energized (switchboards, panelboards, industrial control panels, meter sockets, MCCs) must carry an arc flash label. The label must show the nominal system voltage, the arc flash boundary, and at least one of: the available incident energy with its working distance, or the PPE category (but not both); the minimum arc rating of clothing; or a site-specific PPE level. The equipment owner is responsible for the label and the data behind it, which is reviewed at least every 5 years. When there is no label, don't assume the equipment is safe. You may only use the PPE category tables if the equipment falls within the table's limits for available fault current and clearing time — which you often can't confirm in the field. If you can't, stop and get an incident energy analysis or engineering direction. Labels also go stale: if the system has changed, or the protective device isn't maintained, the real incident energy may be higher than the label says.", "key_points": ["Label shows nominal voltage, arc flash boundary, and incident energy OR PPE category (not both)", "Owner is responsible for labels; data is reviewed at least every 5 years", "No label → don't guess; tables apply only within their fault current and clearing time limits", "A poorly maintained device can make the real incident energy higher than the label"], "standards_reference": "NFPA 70E 130.5(H); NETA L2 Outline Safety H.1–H.2"}, {"title": "What Drives Incident Energy — and How to Reduce It", "content": "Incident energy depends on a handful of factors. Available fault current: more current means more energy. Clearing time: energy is roughly proportional to how long the arc lasts, so clearing time is usually the biggest lever — a breaker that clears in 2 cycles versus 30 cycles can be the difference between Category 1 and a dangerous exposure. Working distance: energy falls off sharply as you move away, so distance is protection. Equipment configuration: an arc inside an enclosure is focused toward the opening, and electrode orientation and gap change the result. Typical clearing times: current-limiting fuses about 0.5 cycle in their current-limiting range, molded case breakers about 1.5 cycles, relay-operated medium-voltage breakers about 5 cycles, and low-voltage power breakers with short-time delay about 20–30 cycles. This is why NETA testing matters: a breaker with stiff lubricant or wrong settings clears slower and raises incident energy. The NEC requires arc energy reduction for breakers rated 1200 A or more (NEC 240.87): energy-reducing maintenance switching, zone-selective interlocking, differential relaying, active arc flash mitigation, or an instantaneous trip set below the arcing current. Remote racking and arc-resistant switchgear also reduce exposure.", "key_points": ["Incident energy rises with fault current and clearing time; it falls sharply with distance", "Clearing time is usually the biggest factor — and maintenance affects it directly", "Typical: fuse 0.5 cycle, MCCB 1.5 cycles, MV relayed breaker 5 cycles, LVPCB short-time 20–30 cycles", "NEC 240.87: arc energy reduction for breakers ≥1200 A (ERMS, ZSI, differential, active mitigation)"], "standards_reference": "NFPA 70E Table 130.7(C)(15)(a) Informational Note; IEEE 1584; NEC 240.87; NETA L2 Outline Safety H.4–H.5"}, {"title": "PPE Categories and Arc-Rated Clothing", "content": "The PPE category method assigns a category from the equipment type and its limits, then specifies PPE by category. Minimum arc ratings: Category 1 is 4 cal/cm², Category 2 is 8 cal/cm², Category 3 is 25 cal/cm², and Category 4 is 40 cal/cm². Typical table examples: panelboards 240 V and below are Category 1 with a 19 in arc flash boundary; panelboards over 240 V up to 600 V are Category 2 with a 3 ft boundary; 600 V class switchgear is Category 4 with a 20 ft boundary; and 1–15 kV metal-clad switchgear is Category 4 with a 40 ft boundary — each only within the table's fault current and clearing time limits. Working distance in these tables is 18 in for low voltage and 36 in for medium voltage. Arc-rated clothing must cover all flammable clothing underneath. Underlayers must be non-melting (no polyester or nylon against the skin). A garment that isn't arc rated can never be counted toward the arc rating of the system. Arc-rated face shields or hoods, hard hats, safety glasses, hearing protection, and leather or rubber gloves complete the PPE for the category.", "key_points": ["Minimum arc ratings: Cat 1 = 4, Cat 2 = 8, Cat 3 = 25, Cat 4 = 40 cal/cm²", "LV table working distance is 18 in; MV is 36 in", "Non-melting underlayers only; non-arc-rated layers add nothing to the arc rating", "Arc-rated clothing must cover all flammable apparel"], "standards_reference": "NFPA 70E 130.7(C)(9), (C)(15) and Table 130.7(C)(15)(a)/(c); NETA L2 Outline Safety D.1"}, {"title": "Rubber Insulating Gloves and Shock Protection", "content": "Rubber insulating gloves are the primary shock protection when you're inside the restricted approach boundary. They're rated by class (per ASTM D120), with maximum use voltages (AC): Class 00 = 500 V, Class 0 = 1,000 V, Class 1 = 7,500 V, Class 2 = 17,000 V, Class 3 = 26,500 V, Class 4 = 36,000 V. Leather protectors are worn over them for mechanical protection. Before every use, inspect the gloves and give them an air test — trap air, roll the cuff, and check for leaks, cuts, ozone cracking and embedded objects. Electrical retest intervals: gloves before first issue and every 6 months after; sleeves and blankets before first issue and every 12 months; covers and line hose when their insulating value is suspect. New equipment can't be placed in service unless it was electrically tested within the previous 12 months. Store gloves unfolded and uncompressed, cuff down in a glove bag, away from sunlight, heat, ozone sources and oils. Electrical-hazard (EH) footwear is only secondary protection and must never be relied on as primary shock protection.", "key_points": ["Glove classes (max use AC): 00 = 500 V, 0 = 1 kV, 1 = 7.5 kV, 2 = 17 kV, 3 = 26.5 kV, 4 = 36 kV", "Inspect and air test gloves before every use; wear leather protectors", "Retest: gloves every 6 months; sleeves and blankets every 12 months", "Store unfolded, away from sunlight, heat and ozone"], "standards_reference": "NFPA 70E 130.7(C)(7) and Table 130.7(C)(7); ASTM D120, F496; OSHA 1910.137; NETA L2 Outline Safety D.2"}, {"title": "Choosing and Caring for Safety Equipment", "content": "Match the equipment to the task and voltage. Voltage detectors and multimeters must be rated for the system voltage and the measurement category of the location — a CAT II meter doesn't belong on a service entrance. Hot sticks (live-line tools) are used for medium-voltage operations like applying grounds, operating fused cutouts or testing with a proximity detector; keep them clean and dry, inspect them before use, and have them tested periodically. Insulated hand tools for low-voltage work are rated and marked 1000 V. Barricades, signs and attendants keep unqualified people out of the boundaries. Fire extinguishers used on energized electrical equipment must be rated Class C (non-conductive agent). The rules for every piece of safety equipment are the same: use it within its rating, inspect it before each use, remove damaged equipment from service, store it so it isn't degraded, and keep its test dates current.", "key_points": ["Meters and detectors must be rated for the voltage and CAT level of the location", "Hot sticks for MV operations; keep clean and dry, inspect before each use, test periodically", "Insulated hand tools are rated 1000 V; fire extinguishers on energized gear must be Class C", "Inspect before use, remove damaged gear, store properly, keep test dates current"], "standards_reference": "NFPA 70E 130.7(D); OSHA 1910.335; NETA L2 Outline Safety E"}], "key_values": [{"label": "Arc flash boundary threshold", "value": "1.2 cal/cm² (5 J/cm²)", "context": "The distance where incident energy would cause the onset of a second-degree burn on bare skin (NFPA 70E 130.5(E))."}, {"label": "PPE category minimum arc ratings", "value": "Cat 1: 4 · Cat 2: 8 · Cat 3: 25 · Cat 4: 40 cal/cm²", "context": "From the PPE category method; clothing must meet or exceed the rating for the category."}, {"label": "Arc flash analysis review interval", "value": "At least every 5 years", "context": "Also updated whenever system changes could affect the results. Applies to label data too."}, {"label": "PPE table working distance", "value": "18 in (LV) / 36 in (MV)", "context": "Incident energy increases for body parts closer than the working distance."}, {"label": "Rubber glove retest interval", "value": "Every 6 months", "context": "Sleeves and blankets: every 12 months. New gloves must have been tested within the prior 12 months."}, {"label": "Class 00 / Class 0 glove max use voltage", "value": "500 V / 1,000 V AC", "context": "Class 1 = 7.5 kV, Class 2 = 17 kV, Class 3 = 26.5 kV, Class 4 = 36 kV (ASTM D120)."}, {"label": "Typical clearing time, LV power breaker with short-time delay", "value": "20–30 cycles", "context": "Versus ~0.5 cycle for current-limiting fuses and ~1.5 cycles for MCCBs — long clearing times drive incident energy up."}, {"label": "NEC arc energy reduction threshold", "value": "Breakers rated 1200 A or higher", "context": "NEC 240.87 requires a method such as ERMS, ZSI, differential relaying or active arc flash mitigation."}], "exam_tips": ["The arc flash boundary is always tied to 1.2 cal/cm². If a question gives you 4 cal/cm², that's the Category 1 minimum rating, not the boundary.", "Know the category ratings cold: 4, 8, 25, 40. Category 3 is 25, not 12.", "You can't use both the incident energy method and the PPE category tables on the same equipment — and you can't convert an incident energy result into a table category.", "If asked what reduces incident energy most effectively, look for faster clearing time or increased distance — not heavier PPE.", "Glove tests: 6 months for gloves, 12 months for sleeves and blankets. The air test is done before every use, not just at the test interval.", "When there's no arc flash label and you can't confirm the fault current and clearing time, the right answer is to stop and get an analysis — not to pick the lowest PPE category."], "summary": "Arc flash PPE starts at the arc flash boundary, where incident energy reaches 1.2 cal/cm². Choose PPE by incident energy analysis or by the PPE category tables, never both, and keep the analysis current (review at least every 5 years). Labels show voltage, boundary, and incident energy or category. With no label and unknown parameters, stop. Incident energy grows with fault current and clearing time and drops with distance, which is why well-maintained, fast-clearing protection is itself a safety control. PPE categories are 4, 8, 25 and 40 cal/cm². Rubber gloves are rated by class, air-tested before each use, and electrically retested every 6 months. All safety equipment must be rated for the task, inspected before use, and kept in test."}$sfty$::jsonb, true, 80, 2, false
)
on conflict (id) do update set
  order_in_phase = excluded.order_in_phase, title = excluded.title,
  description = excluded.description, domain = excluded.domain,
  neta_reference = excluded.neta_reference, estimated_minutes = excluded.estimated_minutes,
  total_questions = excluded.total_questions, content_sections = excluded.content_sections;

-- Replace the safety quiz questions (old module had no answers, stats or child questions)
delete from public.questions where roadmap_module_id in ('19247004-7cb2-4f6b-bb3c-16bde4e6ff7e', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58');

insert into public.questions (
  domain, subdomain, level, concept_type, difficulty, frequency_tier, question, options,
  correct_answer, explanation, trap_pattern, source, question_type, roadmap_module_id
) values
  ('safety-standards', 'codes-standards', 2, 'safety-standards', 1, 1, $sfty$Which of the following is enforceable federal law for electrical safety in general industry in the United States?$sfty$, $sfty${"a": "NFPA 70E", "b": "ANSI/NETA ATS", "c": "OSHA 29 CFR 1910", "d": "IEEE 1584"}$sfty$::jsonb, 'c', $sfty$OSHA regulations in 29 CFR 1910 are federal law. NFPA 70E is a consensus standard that employers use to comply with OSHA's requirements, ANSI/NETA ATS sets acceptance testing specifications, and IEEE 1584 is a guide for arc flash calculations. None of those three is law on its own.$sfty$, $sfty$Choosing NFPA 70E because it's the best-known electrical safety document — it's a consensus standard, not law.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'codes-standards', 2, 'safety-standards', 2, 2, $sfty$Which document primarily governs how electrical equipment is installed, rather than how employees work safely on it?$sfty$, $sfty${"a": "NFPA 70 (National Electrical Code)", "b": "NFPA 70E", "c": "NFPA 70B", "d": "OSHA 29 CFR 1910.146"}$sfty$::jsonb, 'a', $sfty$The NEC (NFPA 70) covers installation requirements. NFPA 70E covers safe work practices, NFPA 70B covers electrical equipment maintenance, and OSHA 1910.146 covers permit-required confined spaces.$sfty$, null, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'risk-assessment', 2, 'conceptual', 2, 1, $sfty$In the NFPA 70E hierarchy of risk controls, which control is considered the MOST effective?$sfty$, $sfty${"a": "Personal protective equipment", "b": "Administrative controls such as procedures and permits", "c": "Engineering controls", "d": "Elimination, such as establishing an electrically safe work condition"}$sfty$::jsonb, 'd', $sfty$The hierarchy runs from most to least effective: elimination, substitution, engineering controls, awareness, administrative controls, and PPE. Removing the hazard entirely by de-energizing is the most effective; PPE is the last line of defense.$sfty$, $sfty$Picking PPE because it's the most visible protection — it ranks last in the hierarchy.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'risk-assessment', 2, 'conceptual', 3, 2, $sfty$A technician is qualified to perform infrared scans on 480 V switchboards. The crew is now asked to rack out a 13.8 kV breaker, a task the technician has never been trained on. Per NFPA 70E, the technician is:$sfty$, $sfty${"a": "Qualified, because qualification applies to all electrical work once earned", "b": "Unqualified for this task, because qualification is specific to equipment and work methods", "c": "Qualified, as long as they wear Category 4 PPE", "d": "Qualified, because medium-voltage work only requires awareness training"}$sfty$::jsonb, 'b', $sfty$NFPA 70E states a person can be qualified for certain equipment and tasks and still be unqualified for others. Qualification comes from training and demonstrated knowledge of that specific equipment or method; PPE doesn't make someone qualified.$sfty$, $sfty$Treating 'qualified person' as a permanent job title rather than task-specific.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'risk-assessment', 2, 'table-lookup', 2, 1, $sfty$What is the limited approach boundary for exposed fixed circuit parts on a 480 V AC system?$sfty$, $sfty${"a": "1 ft 0 in", "b": "10 ft 0 in", "c": "3 ft 6 in", "d": "5 ft 0 in"}$sfty$::jsonb, 'c', $sfty$480 V falls in the 151–750 V range, where the limited approach boundary for exposed fixed circuit parts is 3 ft 6 in (1.0 m). 1 ft 0 in is the restricted approach boundary for the same range, 10 ft applies to exposed movable conductors, and 5 ft 0 in is the limited approach boundary for 751 V–15 kV.$sfty$, $sfty$Mixing up the limited (3 ft 6 in) and restricted (1 ft 0 in) boundaries at 480 V.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'risk-assessment', 2, 'table-lookup', 3, 1, $sfty$For a 13.8 kV system with exposed fixed circuit parts, what are the limited and restricted approach boundaries?$sfty$, $sfty${"a": "Limited 5 ft 0 in; restricted 2 ft 2 in", "b": "Limited 3 ft 6 in; restricted 1 ft 0 in", "c": "Limited 6 ft 0 in; restricted 2 ft 9 in", "d": "Limited 10 ft 0 in; restricted 5 ft 0 in"}$sfty$::jsonb, 'a', $sfty$13.8 kV falls in the 751 V–15 kV range: limited approach 5 ft 0 in (1.5 m), restricted approach 2 ft 2 in (0.7 m). 3 ft 6 in / 1 ft 0 in is the 151–750 V range, and 6 ft 0 in / 2 ft 9 in is the 15.1–36 kV range.$sfty$, null, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'risk-assessment', 2, 'conceptual', 2, 1, $sfty$Who may cross the limited approach boundary of exposed energized parts?$sfty$, $sfty${"a": "Anyone wearing arc-rated clothing", "b": "Only qualified persons, or unqualified persons while escorted and advised by a qualified person", "c": "Only persons holding an energized electrical work permit", "d": "Only the equipment owner's maintenance staff"}$sfty$::jsonb, 'b', $sfty$Unqualified persons may not cross the limited approach boundary unless a qualified person advises them of the hazards and continuously escorts them. The restricted approach boundary is stricter — only qualified persons may cross it.$sfty$, $sfty$Assuming PPE alone permits an unqualified person to approach.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'electrically-safe-work-condition', 2, 'conceptual', 3, 1, $sfty$Which reason justifies performing work on energized equipment instead of establishing an electrically safe work condition?$sfty$, $sfty${"a": "The customer does not want a production outage", "b": "The job will finish faster if the equipment stays energized", "c": "De-energizing would shut down life-support equipment in a hospital", "d": "The technician is qualified and wearing PPE"}$sfty$::jsonb, 'c', $sfty$NFPA 70E allows energized work only when de-energizing creates a greater hazard (such as interrupting life support, emergency alarms or hazardous-location ventilation) or when the task is infeasible de-energized. Convenience, schedule and cost are not justifications, and being qualified with PPE doesn't make energized work acceptable by itself.$sfty$, $sfty$Accepting business inconvenience as a justification for energized work.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'electrically-safe-work-condition', 2, 'safety-standards', 3, 2, $sfty$Which task is exempt from needing an energized electrical work permit when performed by a qualified person using appropriate PPE and safe work practices?$sfty$, $sfty${"a": "Replacing a breaker in an energized panelboard", "b": "Voltage measuring and troubleshooting", "c": "Tightening bus connections inside energized switchgear", "d": "Removing and installing energized meters"}$sfty$::jsonb, 'b', $sfty$Testing, troubleshooting and voltage measuring by qualified persons using appropriate PPE and safe work practices are exempt from the energized electrical work permit. Repair and installation work on energized parts is not exempt. Note the exemption covers only the permit; boundaries and PPE still apply.$sfty$, $sfty$Thinking the permit exemption also removes the PPE requirement.$sfty$, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'confined-space', 2, 'safety-standards', 2, 2, $sfty$When testing the atmosphere before entering a permit-required confined space such as a transformer vault, what should be tested FIRST?$sfty$, $sfty${"a": "Toxic gases such as hydrogen sulfide", "b": "Flammable gases, as a percentage of the lower explosive limit", "c": "Carbon monoxide only", "d": "Oxygen content"}$sfty$::jsonb, 'd', $sfty$Oxygen is tested first because combustible gas meters need adequate oxygen to read correctly, and oxygen deficiency is an immediate hazard. The order is oxygen (19.5–23.5%), then flammables (below 10% LEL), then toxics.$sfty$, null, 'generated', 'roadmap', '19247004-7cb2-4f6b-bb3c-16bde4e6ff7e'),
  ('safety-standards', 'electrically-safe-work-condition', 2, 'conceptual', 2, 1, $sfty$When is equipment considered to be in an electrically safe work condition?$sfty$, $sfty${"a": "As soon as the upstream breaker is opened", "b": "After it is disconnected, locked/tagged, tested for absence of voltage, and grounded where necessary", "c": "When the one-line diagram shows it is isolated", "d": "When the arc flash label shows PPE Category 0"}$sfty$::jsonb, 'b', $sfty$An electrically safe work condition requires all the steps: disconnecting all sources, applying lockout/tagout, verifying absence of voltage, and grounding where necessary. Opening a breaker or checking a drawing alone doesn't establish it.$sfty$, $sfty$Believing that opening the breaker de-energizes the equipment.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'electrically-safe-work-condition', 2, 'safety-standards', 3, 1, $sfty$In the NFPA 70E process for establishing an electrically safe work condition, what is the FIRST step?$sfty$, $sfty${"a": "Apply lockout/tagout devices", "b": "Test for absence of voltage", "c": "Determine all possible sources of electrical supply using up-to-date drawings and tags", "d": "Open the main breaker"}$sfty$::jsonb, 'c', $sfty$The first step is to determine every possible source of supply to the equipment by checking current drawings, diagrams and identification tags. Opening disconnects, applying LOTO and testing all come later in the sequence.$sfty$, null, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'electrically-safe-work-condition', 2, 'safety-standards', 3, 2, $sfty$According to NFPA 70E, which step comes immediately BEFORE applying lockout/tagout devices?$sfty$, $sfty${"a": "Release or block stored mechanical energy", "b": "Verify absence of voltage", "c": "Apply temporary protective grounds", "d": "Hold the job briefing"}$sfty$::jsonb, 'a', $sfty$The order is: identify sources, open disconnects, visually verify, release stored electrical energy, release or block stored mechanical energy, then apply LOTO. Verifying absence of voltage and grounding come after LOTO.$sfty$, $sfty$Placing the voltage test before lockout.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'isolation-grounding', 2, 'conceptual', 2, 1, $sfty$A technician tests a 480 V circuit and reads zero, then puts the meter away. What step of the live-dead-live method was skipped?$sfty$, $sfty${"a": "Testing phase-to-phase", "b": "Applying temporary grounds", "c": "Checking the arc flash label", "d": "Re-verifying the meter on a known live source after the test"}$sfty$::jsonb, 'd', $sfty$Live-dead-live requires proving the meter on a known source before AND after testing the circuit. Without the final check, a meter that failed during the test could show zero on an energized circuit.$sfty$, $sfty$Assuming a meter that worked before the test still works afterward.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'isolation-grounding', 2, 'safety-standards', 3, 1, $sfty$When verifying absence of voltage on a three-phase, 480 V system, how must each phase be tested?$sfty$, $sfty${"a": "Phase-to-ground only", "b": "Phase-to-phase and phase-to-ground", "c": "Phase-to-phase only", "d": "With a noncontact voltage detector on each phase"}$sfty$::jsonb, 'b', $sfty$NFPA 70E requires testing each phase conductor both phase-to-phase and phase-to-ground. Noncontact detectors are only permitted for this on systems over 1000 V.$sfty$, $sfty$Choosing a noncontact detector, which isn't permitted at 480 V.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'lockout-tagout', 2, 'conceptual', 2, 1, $sfty$Under an individual lockout procedure, who is permitted to remove a worker's lock under normal circumstances?$sfty$, $sfty${"a": "Any qualified person on the crew", "b": "The shift supervisor", "c": "Only the person who applied the lock", "d": "The equipment owner's representative"}$sfty$::jsonb, 'c', $sfty$Only the person who applied the lock removes it. The rare exception, when that person has left the site, requires a documented procedure: verify they're gone, try to contact them, and inform them before they return to work.$sfty$, $sfty$Assuming a supervisor can remove a worker's lock at will.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'lockout-tagout', 2, 'safety-standards', 3, 2, $sfty$When may a tag be used WITHOUT a lock on an energy-isolating device?$sfty$, $sfty${"a": "Whenever the job will take less than one hour", "b": "Only when a lock can't be applied, and an additional safety measure (such as removing a fuse) is used", "c": "When the equipment is below 600 V", "d": "Never; tags are prohibited under NFPA 70E"}$sfty$::jsonb, 'b', $sfty$A tag alone is permitted only where a lock can't physically be applied, and it must be backed by an additional measure that provides equivalent safety, such as removing a fuse, opening an extra disconnect or removing a drawout breaker.$sfty$, null, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'isolation-grounding', 2, 'conceptual', 4, 2, $sfty$A crew has locked out the utility feed to a switchboard. Which additional source could still re-energize the bus?$sfty$, $sfty${"a": "A standby generator connected through an automatic transfer switch", "b": "The building's lighting circuits", "c": "The arc flash label", "d": "The ground grid"}$sfty$::jsonb, 'a', $sfty$Standby generators feeding through a transfer switch are a classic backfeed source, along with UPS, PV and battery storage, tie breakers and backfed PTs. Every source must be identified and have its own isolation point included in the lockout.$sfty$, $sfty$Stopping after locking out the normal (utility) source.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'isolation-grounding', 2, 'conceptual', 3, 2, $sfty$When applying temporary protective grounds to a de-energized conductor, what is the correct sequence?$sfty$, $sfty${"a": "Connect the conductor end first, then the ground end", "b": "Apply grounds first, then verify absence of voltage", "c": "Connect both ends at the same time using two workers", "d": "Verify absence of voltage, connect the ground end first, then the conductor end"}$sfty$::jsonb, 'd', $sfty$Grounds are applied only after absence of voltage is verified. The ground end is connected first and removed last, so the lead is never attached to a conductor without a path to ground.$sfty$, $sfty$Grounding before verifying absence of voltage.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'isolation-grounding', 2, 'safety-standards', 3, 2, $sfty$Temporary protective grounding equipment must be rated primarily for which of the following?$sfty$, $sfty${"a": "The nominal system voltage only", "b": "The ambient temperature at the work location", "c": "The available fault current and the protective device clearing time", "d": "The load current of the circuit"}$sfty$::jsonb, 'c', $sfty$Grounds must carry the available fault current until the protective device clears it, so they're sized for fault current and clearing time (per ASTM F855). An undersized ground can melt and fail during the fault it's meant to protect against.$sfty$, $sfty$Sizing grounds by voltage or load current.$sfty$, 'generated', 'roadmap', 'b7e2c1a4-5d3f-4e8a-9c61-2f0d8a4b7e11'),
  ('safety-standards', 'incident-energy-analysis', 2, 'table-lookup', 2, 1, $sfty$The arc flash boundary is defined as the distance at which incident energy equals:$sfty$, $sfty${"a": "4 cal/cm²", "b": "8 cal/cm²", "c": "1.2 cal/cm²", "d": "40 cal/cm²"}$sfty$::jsonb, 'c', $sfty$The arc flash boundary is where incident energy equals 1.2 cal/cm² (5 J/cm²), the onset of a second-degree burn on bare skin. 4 and 8 cal/cm² are the minimum arc ratings for PPE Categories 1 and 2, and 40 cal/cm² is Category 4.$sfty$, $sfty$Confusing the 1.2 cal/cm² boundary threshold with the 4 cal/cm² Category 1 rating.$sfty$, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'ppe', 2, 'table-lookup', 2, 1, $sfty$What is the minimum arc rating of clothing for Arc Flash PPE Category 3?$sfty$, $sfty${"a": "25 cal/cm²", "b": "12 cal/cm²", "c": "8 cal/cm²", "d": "40 cal/cm²"}$sfty$::jsonb, 'a', $sfty$The minimum arc ratings are 4 cal/cm² (Category 1), 8 (Category 2), 25 (Category 3) and 40 (Category 4).$sfty$, $sfty$Assuming the categories increase evenly (e.g., 12 for Category 3).$sfty$, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'incident-energy-analysis', 2, 'conceptual', 3, 1, $sfty$Which change would MOST effectively reduce the incident energy a worker is exposed to during an arc flash on low-voltage switchgear?$sfty$, $sfty${"a": "Wearing a higher-rated arc flash suit", "b": "Reducing the protective device's clearing time, for example with an energy-reducing maintenance switch", "c": "Adding a second arc flash label", "d": "Replacing copper bus with aluminum"}$sfty$::jsonb, 'b', $sfty$Incident energy is roughly proportional to how long the arc lasts, so faster clearing (maintenance switching, zone-selective interlocking, differential relaying) directly reduces it. A heavier suit protects the worker better but doesn't reduce the incident energy itself.$sfty$, $sfty$Choosing more PPE, which protects against the energy but doesn't reduce it.$sfty$, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'incident-energy-analysis', 2, 'conceptual', 3, 2, $sfty$Why can poor maintenance of a circuit breaker increase arc flash hazard?$sfty$, $sfty${"a": "It lowers the system voltage", "b": "It reduces the available fault current", "c": "It changes the shock approach boundaries", "d": "A sluggish mechanism or wrong settings can increase the clearing time, raising incident energy"}$sfty$::jsonb, 'd', $sfty$NFPA 70E requires the incident energy analysis to consider the protective device's clearing time and its condition of maintenance. A breaker with hardened lubricant or incorrect settings may clear slower than the study assumed, so the actual incident energy can exceed the label.$sfty$, null, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'incident-energy-analysis', 2, 'safety-standards', 2, 1, $sfty$What must an arc flash label include?$sfty$, $sfty${"a": "Nominal system voltage, arc flash boundary, and incident energy with working distance or the PPE category (not both)", "b": "Only the PPE category", "c": "The available fault current and the utility account number", "d": "The date of the last NETA acceptance test"}$sfty$::jsonb, 'a', $sfty$The label must include the nominal voltage, the arc flash boundary, and at least one of: incident energy with working distance or PPE category (but not both), minimum arc rating of clothing, or site-specific PPE.$sfty$, null, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'incident-energy-analysis', 2, 'safety-standards', 3, 2, $sfty$A 480 V panel has no arc flash label, and the available fault current and clearing time are unknown. What should the technician do?$sfty$, $sfty${"a": "Use PPE Category 1 because it's a panelboard", "b": "Proceed without arc flash PPE since the voltage is under 600 V", "c": "Stop and obtain an incident energy analysis or engineering direction before energized work", "d": "Use the arc flash boundary for 120 V systems"}$sfty$::jsonb, 'c', $sfty$The PPE category tables can only be used when the equipment falls within their fault current and clearing time limits. If those can't be confirmed and there's no label, the hazard is unknown — stop and get an analysis or engineering direction rather than guessing.$sfty$, $sfty$Defaulting to the lowest category when the parameters are unknown.$sfty$, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'incident-energy-analysis', 2, 'safety-standards', 2, 2, $sfty$How often must an incident energy analysis be reviewed for accuracy, even if the system hasn't changed?$sfty$, $sfty${"a": "Every year", "b": "At intervals not exceeding 5 years", "c": "Every 10 years", "d": "Only when a new label is ordered"}$sfty$::jsonb, 'b', $sfty$NFPA 70E requires the incident energy analysis (and the label data) to be reviewed at intervals not exceeding 5 years, and updated whenever changes to the distribution system could affect the results.$sfty$, null, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'ppe', 2, 'table-lookup', 2, 1, $sfty$How often must rubber insulating gloves in service be electrically retested?$sfty$, $sfty${"a": "Every 12 months", "b": "Every 3 months", "c": "Only when they fail an air test", "d": "Every 6 months"}$sfty$::jsonb, 'd', $sfty$Rubber insulating gloves are electrically tested before first issue and every 6 months after. Sleeves and blankets are every 12 months. An air test and visual inspection are also done before every use.$sfty$, $sfty$Using the 12-month interval that applies to sleeves and blankets.$sfty$, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'ppe', 2, 'table-lookup', 3, 2, $sfty$What is the lowest glove class rated for use on a 4,160 V system?$sfty$, $sfty${"a": "Class 1 (7,500 V maximum use)", "b": "Class 0 (1,000 V maximum use)", "c": "Class 00 (500 V maximum use)", "d": "Class 3 (26,500 V maximum use)"}$sfty$::jsonb, 'a', $sfty$Class 0 is rated for 1,000 V and Class 00 for 500 V, both too low for 4,160 V. Class 1, with a 7,500 V maximum use voltage, is the lowest class that covers 4.16 kV. Class 3 would also work but isn't the lowest.$sfty$, null, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58'),
  ('safety-standards', 'safety-equipment', 2, 'conceptual', 2, 2, $sfty$Which type of fire extinguisher is appropriate for a fire involving energized electrical equipment?$sfty$, $sfty${"a": "Class A water extinguisher", "b": "Class K wet chemical extinguisher", "c": "Class C rated extinguisher with a non-conductive agent", "d": "Any extinguisher, as long as the operator wears rubber gloves"}$sfty$::jsonb, 'c', $sfty$Class C extinguishers use non-conductive agents (such as CO₂ or dry chemical) suitable for energized electrical equipment. Water-based Class A extinguishers conduct electricity and create a shock hazard, and Class K is for cooking oils.$sfty$, null, 'generated', 'roadmap', 'c4a9f3d2-8e1b-4b6f-a7d5-3e9c0b2f6a58');

commit;
